package com.slss.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="audit_logs")
public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String actor; @Column(nullable=false) String action; @Column(name="target_type") String targetType; @Column(name="target_id") String targetId; @Column(columnDefinition="TEXT") String details; @Column(name="ip_address") String ipAddress; @Column(nullable=false) boolean success; @Column(name="created_at",nullable=false) Instant createdAt=Instant.now(); public Long getId(){return id;} public String getActor(){return actor;} public String getAction(){return action;} public String getTargetType(){return targetType;} public String getTargetId(){return targetId;} public String getDetails(){return details;} public String getIpAddress(){return ipAddress;} public boolean isSuccess(){return success;} public Instant getCreatedAt(){return createdAt;} public void setActor(String v){actor=v;} public void setAction(String v){action=v;} public void setTargetType(String v){targetType=v;} public void setTargetId(String v){targetId=v;} public void setDetails(String v){details=v;} public void setIpAddress(String v){ipAddress=v;} public void setSuccess(boolean v){success=v;} }
